def test_newest_queue_id():
    records = [
        {"id": "1", "created_at": "2023-01-01T00:00:00"},
        {"id": "2", "created_at": "2023-01-02T00:00:00"}
    ]
    assert newest_queue_id(records) == "2"
    assert newest_queue_id([]) is None

def flag_large_backorder_totals(rows: list[dict[str, object]], threshold: float) -> list[dict[str, object]]:
    """Flag backorder rows whose total crosses the review threshold."""
    flagged: list[dict[str, object]] = []
    for row in rows:
        if float(row["total"]) > threshold:
            flagged.append(row)
    return flagged

